package com.fasterxml.jackson.databind.deser.std;

import com.fasterxml.jackson.core.*;
import com.fasterxml.jackson.core.JsonParser;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.DeserializationContext;
import com.fasterxml.jackson.databind.annotation.JacksonStdImpl;
import com.fasterxml.jackson.databind.deser.ContextualDeserializer;
import com.fasterxml.jackson.databind.deser.std.TypeDeserializer;
import com.fasterxml.jackson.databind.jsontype.TypeDeserializer;
import com.fasterxml.jackson.databind.util.ObjectBuffer;
import java.io.*;
import java.io.IOException;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

/**
 * Unit tests for StringArrayDeserializer#deserializeWithType
 */
public class StringArrayDeserializer_deserializeWithType_TriageGen0Test {

    private StringArrayDeserializer deserializer;
    private JsonParser jsonParser;
    private DeserializationContext deserializationContext;
    private TypeDeserializer typeDeserializer;

    @Before
    public void setUp() {
        deserializer = new StringArrayDeserializer();
        jsonParser = Mockito.mock(JsonParser.class);
        deserializationContext = Mockito.mock(DeserializationContext.class);
        typeDeserializer = Mockito.mock(TypeDeserializer.class);
    }

    @Test
    public void testDeserializeWithType_ReturnsExpectedObject() throws IOException {
        // Arrange
        String[] expectedResult = {"apple", "banana", "cherry"};
        when(typeDeserializer.deserializeTypedFromArray(jsonParser, deserializationContext))
                .thenReturn(expectedResult);

        // Act
        Object actualResult = deserializer.deserializeWithType(jsonParser, deserializationContext, typeDeserializer);

        // Assert
        assertEquals(expectedResult, actualResult);
        verify(typeDeserializer).deserializeTypedFromArray(jsonParser, deserializationContext);
    }

    @Test
    public void testDeserializeWithType_ReturnsNull() throws IOException {
        // Arrange
        when(typeDeserializer.deserializeTypedFromArray(jsonParser, deserializationContext))
                .thenReturn(null);

        // Act
        Object actualResult = deserializer.deserializeWithType(jsonParser, deserializationContext, typeDeserializer);

        // Assert
        assertEquals(null, actualResult);
        verify(typeDeserializer).deserializeTypedFromArray(jsonParser, deserializationContext);
    }

    @Test(expected = IOException.class)
    public void testDeserializeWithType_ThrowsIOException() throws IOException {
        // Arrange
        when(typeDeserializer.deserializeTypedFromArray(jsonParser, deserializationContext))
                .thenThrow(new IOException("Simulated IO error"));

        // Act
        deserializer.deserializeWithType(jsonParser, deserializationContext, typeDeserializer);

        // Assert handled by expected exception
    }
}
